-- Pavagada One schema for Turso/libSQL. Apply with: turso db shell <db> < supabase/migrations/0001_init.sql
PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, phone TEXT, role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','merchant','admin','rider')), is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE addresses (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), label TEXT NOT NULL, address_line TEXT NOT NULL, landmark TEXT, latitude REAL, longitude REAL, is_default INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, image_url TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE shops (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, phone TEXT, address TEXT NOT NULL, latitude REAL, longitude REAL, is_open INTEGER NOT NULL DEFAULT 1, is_approved INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), category_id TEXT REFERENCES categories(id), name TEXT NOT NULL, description TEXT, price_paise INTEGER NOT NULL CHECK(price_paise >= 0), image_url TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inventory (product_id TEXT PRIMARY KEY REFERENCES products(id), quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity >= 0), low_stock_threshold INTEGER NOT NULL DEFAULT 5, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE carts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id), shop_id TEXT NOT NULL REFERENCES shops(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cart_items (id TEXT PRIMARY KEY, cart_id TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), UNIQUE(cart_id, product_id));
CREATE TABLE orders (id TEXT PRIMARY KEY, order_no TEXT NOT NULL UNIQUE, customer_id TEXT NOT NULL REFERENCES users(id), shop_id TEXT NOT NULL REFERENCES shops(id), address_id TEXT NOT NULL REFERENCES addresses(id), status TEXT NOT NULL DEFAULT 'placed' CHECK(status IN ('placed','accepted','preparing','ready','assigned','out_for_delivery','delivered','cancelled')), subtotal_paise INTEGER NOT NULL, delivery_fee_paise INTEGER NOT NULL DEFAULT 0, total_paise INTEGER NOT NULL, payment_method TEXT NOT NULL CHECK(payment_method IN ('cash_on_delivery','online')), payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','paid','failed','refunded')), notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id TEXT REFERENCES products(id), product_name TEXT NOT NULL, unit_price_paise INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity > 0), total_paise INTEGER NOT NULL);
CREATE TABLE order_status_history (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, status TEXT NOT NULL, changed_by TEXT REFERENCES users(id), note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE delivery_assignments (id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), rider_id TEXT NOT NULL REFERENCES users(id), assigned_by TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','picked_up','delivered','cancelled')), assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, delivered_at TEXT);
CREATE TABLE payments (id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), provider TEXT NOT NULL, provider_payment_id TEXT, amount_paise INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'INR', status TEXT NOT NULL DEFAULT 'pending', payload_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, data_json TEXT, read_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_products_shop ON products(shop_id); CREATE INDEX idx_orders_customer ON orders(customer_id,created_at); CREATE INDEX idx_orders_shop ON orders(shop_id,status); CREATE INDEX idx_notifications_user ON notifications(user_id,created_at);
-- Turso does not provide Supabase-style RLS. Enforce access in every API query using the authenticated user id + role; never expose the database token to clients.